type RingBuffer struct {
  buf  []string
  head int
  tail int
  size int
}

func NewRingBuffer(capacity int) *RingBuffer {
  return &RingBuffer{
    buf: make([]string, capacity),
  }
}

func (r *RingBuffer) Push(item string) bool {
  if r.size == len(r.buf) {
    return false
  }
  r.buf[r.tail] = item
  r.tail = (r.tail + 1) % len(r.buf)
  r.size++
  return true
}
